import{_ as t,o as a,c as s,a0 as i}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Walkthrough: Deploying the knowledge base to single-machine production and verifying stop/start and degradation","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/single-machine-production"},"headers":[],"relativePath":"en/tutorials/single-machine-production.md","filePath":"en/tutorials/single-machine-production.md"}'),n={name:"en/tutorials/single-machine-production.md"};function o(r,e,d,h,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="walkthrough-deploying-the-knowledge-base-to-single-machine-production-and-verifying-stop-start-and-degradation" tabindex="-1">Walkthrough: Deploying the knowledge base to single-machine production and verifying stop/start and degradation <a class="header-anchor" href="#walkthrough-deploying-the-knowledge-base-to-single-machine-production-and-verifying-stop-start-and-degradation" aria-label="Permalink to &quot;Walkthrough: Deploying the knowledge base to single-machine production and verifying stop/start and degradation&quot;">​</a></h1><p>This chapter answers &quot;how does the template reach single-machine production&quot;. One Docker host, one Caddy TLS entry; the static web assets are served directly by Caddy, and the API, Worker, PostgreSQL, Redis and RustFS all stay on the internal network with no published ports. Database migrations and storage initialization are always explicit. The production composition is not a copy of the development <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/compose.yaml" target="_blank" rel="noreferrer">compose</a>: it has its own <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/compose.production.yaml" target="_blank" rel="noreferrer">composition file</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/deploy/production/Dockerfile" target="_blank" rel="noreferrer">image build</a> and <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/deploy/production/Caddyfile" target="_blank" rel="noreferrer">entry configuration</a>, and tests lock in those differences.</p><h2 id="_1-prepare-the-deployment-environment-and-secrets" tabindex="-1">1. Prepare the deployment environment and secrets <a class="header-anchor" href="#_1-prepare-the-deployment-environment-and-secrets" aria-label="Permalink to &quot;1. Prepare the deployment environment and secrets&quot;">​</a></h2><p>Copy the template and fill in the deployment environment file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/production/env.production.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.production</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$EDITOR .env.production</span></span></code></pre></div><p>The minimum set to change: <code>DOMAIN</code> (the TLS domain; Caddy issues certificates automatically from it — public domains use ACME, localhost uses a local CA), <code>POSTGRES_PASSWORD</code>, and <code>S3_ACCESS_KEY</code>/<code>S3_SECRET_KEY</code>. Leaving <code>MAIL_SMTP_HOST</code> empty means mail is off (registration and writing are unaffected; only reset mail is not sent). Enabling SMTP also requires <code>MAIL_ENCRYPTION_KEY</code> (32-byte hex, identical for api and worker); even if SMTP becomes unreachable afterwards, registration and writing keep working and delivery jobs stay in the queue retrying under their leases. Leaving <code>TELEMETRY_ENDPOINT</code> empty means no OTLP reporting; an unreachable collector never blocks the business.</p><p>This file carries production secrets and is excluded by <code>.gitignore</code> and <code>.dockerignore</code> — it never enters an image or the repository. The services&#39; <code>env_file</code> in the composition file reads the <code>ENV_FILE</code> environment variable, while <code>--env-file</code> only feeds interpolation — the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/justfile" target="_blank" rel="noreferrer">justfile</a> <code>production-*</code> recipes already pass <code>ENV_FILE</code> for you; when calling docker compose by hand you must carry it yourself. The semantics and validation rules of every key are in the <a href="./../reference/config">generated configuration reference</a> or the comments inside <code>deploy/production/env.production.example</code>.</p><h2 id="_2-build-start-and-migrate-explicitly" tabindex="-1">2. Build, start and migrate explicitly <a class="header-anchor" href="#_2-build-start-and-migrate-explicitly" aria-label="Permalink to &quot;2. Build, start and migrate explicitly&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # Build the web assets and app images (no env file needed)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Dependencies → explicit migration → app</span></span></code></pre></div><p>The <code>production-up</code> order is deliberate: first <code>--wait</code> until PostgreSQL/Redis/RustFS are healthy, then run <code>migrate</code> and <code>storage-init</code> in one-shot containers (the compose <code>ops</code> profile, invisible to a plain <code>up</code>), and only then start api, worker and caddy and wait for health. The API and the Worker never migrate silently: behavior tests start the binaries against an empty database and assert that <code>/health/ready</code> keeps returning <code>503</code> (<code>database.unavailable</code>/<code>worker.unavailable</code>), that the <code>public</code> schema still has zero tables after five seconds, and that the processes stay alive (<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/apps/api/tests/migration.rs" target="_blank" rel="noreferrer">API side</a>, <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/apps/worker/tests/no_implicit_migration.rs" target="_blank" rel="noreferrer">Worker side</a>).</p><p>The image build is multi-stage: the Rust build stage mounts registry/target caches, the runtime is slim Debian with a non-root user and a read-only root filesystem (<code>read_only: true</code>, tmpfs <code>/tmp</code>), and base images are pinned by digest. <code>migrations/</code> is embedded at compile time by <code>sqlx::migrate!</code>, so it must stay inside the build context.</p><h2 id="_3-verify-the-entry-and-the-main-journey" tabindex="-1">3. Verify the entry and the main journey <a class="header-anchor" href="#_3-verify-the-entry-and-the-main-journey" aria-label="Permalink to &quot;3. Verify the entry and the main journey&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-smoke</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/scripts/production-smoke.mjs" target="_blank" rel="noreferrer">smoke script</a> generates a fresh set of secrets, boots the complete production composition, and then goes through the real Caddy TLS chain: entry checks (<code>/health/live</code> 200, the landing page with HSTS and CSP, plain-HTTP redirect), the main journey (register an owner, write a document, upload an attachment and read it back), restart persistence, degraded behavior for Redis/RustFS/PostgreSQL failures, queued export recovery after a Worker outage, and graceful stops of both the API and the Worker. The whole journey deliberately runs in an environment where &quot;mail is configured but SMTP is unreachable and the telemetry collector is down&quot; — registration and writing stay usable throughout, which is exactly what the degradation matrix promises. Each phase failure raises with a <code>[phase-name]</code> prefix, and the script finishes with an automatic <code>down -v</code> cleanup.</p><p>Manual spot checks of the entry also work:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -I</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$DOMAIN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Expect 308 → https</span></span></code></pre></div><p>Presigned object URLs work through the entry because the application signs with <code>S3_PUBLIC_ENDPOINT</code> (that is, <code>APP_ORIGIN</code>), and the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/deploy/production/Caddyfile" target="_blank" rel="noreferrer">Caddyfile</a> forwards <code>/&lt;bucket&gt;/*</code> verbatim to rustfs:9000 — path and Host unchanged — so the v4 signature stays valid.</p><h2 id="_4-stop-restart-and-degradation-rules" tabindex="-1">4. Stop, restart and degradation rules <a class="header-anchor" href="#_4-stop-restart-and-degradation-rules" aria-label="Permalink to &quot;4. Stop, restart and degradation rules&quot;">​</a></h2><p><code>docker compose restart api worker</code> (or stop/start) verifies one thing: the session cookie and the data survive container replacement, because state lives only in PostgreSQL and the object volumes. Stop timeouts in the composition file match the in-process budgets:</p><table tabindex="0"><thead><tr><th>Container</th><th>In-process stop budget</th><th>stop_grace_period</th></tr></thead><tbody><tr><td>api</td><td>3s HTTP drain + 1s connection pool + bounded telemetry flush (≤15s total)</td><td>30s</td></tr><tr><td>worker</td><td>api budget + <code>JOB_SHUTDOWN_SECS</code> (default 10s) to finish held work (≤25s total)</td><td>45s</td></tr><tr><td>others</td><td>No custom logic; the default stop is fine</td><td>10–30s</td></tr></tbody></table><p>The smoke script measures this: api&#39;s stop must take clearly less than the 30s grace period (proof that it exited by itself instead of being killed), with <code>draining HTTP requests</code> in the logs; the same applies to the Worker, with <code>stopping worker claims and draining current work</code> in the logs.</p><p>Non-core dependency failures degrade according to the spec matrix, and the smoke covers every row:</p><table tabindex="0"><thead><tr><th>Failure</th><th>Behavior</th></tr></thead><tbody><tr><td>PostgreSQL stops</td><td><code>/health/ready</code> turns 503, business reads return a controlled 503 (with <code>request_id</code>), and recovery brings back 200 without a restart</td></tr><tr><td>Redis stops</td><td>Cache falls back to the database, registration and writing continue; the readiness probe only looks at the database, so the container is not wrongly marked unhealthy</td></tr><tr><td>RustFS stops</td><td>Markdown stays readable in PostgreSQL; new upload PUTs fail and completion returns a controlled 503; retries succeed after recovery</td></tr><tr><td>Mail configured but unreachable</td><td>Registration and writing unaffected; reset/verification mail jobs stay in the queue retrying under their leases</td></tr><tr><td>Telemetry collector unreachable</td><td>Business unaffected; batch exports are bounded and flush by their deadline at process stop</td></tr></tbody></table><p>A Worker shutdown loses no work: export requests are accepted with <code>202</code> as usual, and the Worker claims and completes them from the database job table when it returns (the lease is protected by <code>JOB_LEASE_SECS</code>).</p><h2 id="_5-upgrades-and-the-maintenance-window" tabindex="-1">5. Upgrades and the maintenance window <a class="header-anchor" href="#_5-upgrades-and-the-maintenance-window" aria-label="Permalink to &quot;5. Upgrades and the maintenance window&quot;">​</a></h2><p>An upgrade = new image + explicit migration, in a fixed order:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-down</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # Or stop only api worker for a rolling window</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # Run the new migrations explicitly</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-up</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ENV_FILE=.env.production</span></span></code></pre></div><p>Failure handling falls out of the same command naturally: when the <code>migrate</code> one-shot container exits non-zero, <code>production-up</code> aborts before starting the application, the database stays at the last successful migration, the old containers are stopped and the new ones have not taken over — fix the problem (most often a missing key in the environment file or an unreachable database) and rerun <code>production-migrate</code>; already-applied migrations are not executed twice.</p><p><code>docker compose up -d</code> only recreates services whose image or configuration changed; data volumes (PostgreSQL data, object storage, Caddy certificates) persist across upgrades. Never enter a container by hand to change data — for recovery, see <a href="./backup-restore">backup and isolated-environment restore drill</a>.</p><h2 id="_6-run-this-chapter-s-checks" tabindex="-1">6. Run this chapter&#39;s checks <a class="header-anchor" href="#_6-run-this-chapter-s-checks" aria-label="Permalink to &quot;6. Run this chapter&#39;s checks&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/tooling/production-compose.test.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # Composition file and security properties</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> production-smoke</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # Real composition, full journey</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check</span></span></code></pre></div><p>The <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/tests/tooling/production-compose.test.mjs" target="_blank" rel="noreferrer">composition tests</a> verify the production composition&#39;s structural properties on every <code>just check</code>: only Caddy publishes ports, every long-running service has a health check and resource limits, the migration services hide in the <code>ops</code> profile and are depended on by nothing, no migrate in the API/Worker commands, read-only root filesystems, no real secrets in the env template, and <code>.dockerignore</code> excluding <code>.secrets</code> and <code>.env*</code>. What matters: migrations are explicit, there is exactly one entry, failures degrade along the matrix, and the grace periods match the stop budgets.</p><hr><p>Source version：<code>68f0788f4b1a</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/68f0788f4b1af261bfde044a0e7cd18429fcce6f/docs/tutorials/21-single-machine-production.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,34)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
